#!/bin/bash
set -e
# Absolue path to this script
SCRIPT_DIR=$(dirname "$(realpath $0)")
# Absolute paths to useful directories
ASTRA_SIM_DIR="${SCRIPT_DIR:?}"/../../astra-sim
NS3_DIR="${SCRIPT_DIR:?}"/../../extern/network_backend/ns-3
WORKSPACE_DIR="${SCRIPT_DIR:?}"/../..
CHAKRA_PROTO_DIR="${WORKSPACE_DIR}/extern/graph_frontend/chakra/schema/protobuf"

# Functions
function setup {
    # C++ et_def sources are generated by CMake (bundled protobuf submodule + protoc).
    # Optionally generate Python bindings if protoc is available.
    if [[ ! -f "${CHAKRA_PROTO_DIR}/et_def_pb2.py" ]] && command -v protoc >/dev/null 2>&1; then
        protoc et_def.proto \
            --proto_path="${CHAKRA_PROTO_DIR}" \
            --python_out="${CHAKRA_PROTO_DIR}"
    fi

    # ns-3 runtime prerequisite
    mkdir -p "${NS3_DIR}/scratch/output"
    if [[ ! -f "${NS3_DIR}/scratch/output/flow.txt" ]]; then
        echo "0" > "${NS3_DIR}/scratch/output/flow.txt"
    fi
}
function compile {
    cd "${NS3_DIR}"
    ./ns3 configure --enable-mpi
    ./ns3 build AstraSimNetwork -j $(nproc)
    cd "${SCRIPT_DIR:?}"
}
function cleanup {
    cd "${NS3_DIR}"
    ./ns3 distclean
    cd "${SCRIPT_DIR:?}"
}
function cleanup_result {
    echo '0'
}
function debug {
    cd "${NS3_DIR}"
    ./ns3 configure --enable-mpi --build-profile debug
    ./ns3 build AstraSimNetwork -j 12 -v
    cd "${NS3_DIR}/build/scratch"
}
# Main Script
case "$1" in
-l|--clean)
    cleanup;;
-lr|--clean-result)
    cleanup
    cleanup_result;;
-d|--debug)
    setup
    debug;;
-c|--compile|"")
    setup
    compile;;
-h|--help|*)
    printf "Invalid option '$1'.\n";;
esac
